alter table Data_Police_Relation ADD (POLICE_EMERGENT NUMBER default 1) ;
comment on column DATA_POLICE_RELATION.POLICE_EMERGENT is '告警是否紧急 0：紧急  1：非紧急';

alter table detection_info ADD  (POLICE_EMERGENT NUMBER default 1);
comment on column detection_info.POLICE_EMERGENT is '告警是否紧急 0：紧急  1：非紧急'; 

alter table detection_info_new ADD  (POLICE_EMERGENT NUMBER default 1);
comment on column detection_info_new.POLICE_EMERGENT  is '告警是否紧急 0：紧急  1：非紧急';

alter table detection_info_warning ADD (POLICE_EMERGENT NUMBER default 1);
comment on column detection_info_warning.POLICE_EMERGENT  is '告警是否紧急 0：紧急  1：非紧急';


